import{_ as d,o,c as t,a2 as c}from"./chunks/framework.ChW7XBuO.js";const g=JSON.parse('{"title":"图执行引擎","description":"rolebox v2 图执行引擎详解 — 节点生命周期、join 评估、信号传播、级联取消、循环组、审批门、预算、持久化与恢复","frontmatter":{"title":"图执行引擎","description":"rolebox v2 图执行引擎详解 — 节点生命周期、join 评估、信号传播、级联取消、循环组、审批门、预算、持久化与恢复"},"headers":[],"relativePath":"04-Advanced/graph-engine.md","filePath":"04-Advanced/graph-engine.md"}'),a={name:"04-Advanced/graph-engine.md"};function r(n,e,i,s,l,p){return o(),t("div",null,[...e[0]||(e[0]=[c(`<h1 id="图执行引擎-graph-engine" tabindex="-1">图执行引擎（Graph Engine） <a class="header-anchor" href="#图执行引擎-graph-engine" aria-label="Permalink to &quot;图执行引擎（Graph Engine）&quot;">​</a></h1><blockquote><p><strong>相关文档：</strong> <a href="/rolebox-docs/02-Guide/collaboration-graph.html">协作图</a> — 声明式 <code>collaboration:</code> 路径 | <a href="/rolebox-docs/04-Advanced/runtime-behavior.html">运行时行为</a> — 协作图运行时状态 | <a href="/rolebox-docs/04-Advanced/termination-conditions.html">终止条件</a> — 循环终止与超时 | <a href="/rolebox-docs/03-Reference/tool-catalog.html">工具目录：Graph 工具</a> — <code>graph_*</code> 工具参数详解</p></blockquote><p>rolebox 把「谁把工作传给谁」这个问题抽象成一张有向图来执行：图中的每个<strong>节点</strong>代表一次派发给子代理的工作，<strong>边</strong>代表工作之间的流转关系。一个统一的<strong>图执行引擎</strong>负责把这张图跑起来——它决定节点何时开始、何时结束、中途要不要人工确认、以及万一崩溃怎么接着跑。理解这张图，你就理解了 rolebox v2 的多代理协作机制。</p><div class="tip custom-block"><p class="custom-block-title">先读：核心术语速览</p><ul><li><strong>Graph 执行引擎</strong> — rolebox 统一的多代理编排引擎：把「谁把工作传给谁」建模成一张有向图来执行。</li><li><strong>节点（node）与边（edge）</strong> — 图的基本单元：节点 = 一次派发给子代理的工作；边 = 工作之间的流转关系（<code>from → to</code>）。</li><li><strong><code>{agent, prompt}</code> 元组</strong> — 图节点的内容：<code>agent</code> 是承接该节点的角色，<code>prompt</code> 是交给它的任务指令。节点与角色无关，任何角色都可承接。</li><li><strong>节点生命周期（NodeStatus）</strong> — 一个节点从注册到结束所经历的状态序列（pending → ready → running → … → done）。</li><li><strong>EngineRuntime / EngineState / EnginePhase</strong> — 每次图执行由一个运行时（EngineRuntime）承载；它持有该图的运行状态（EngineState）与生命周期阶段（EnginePhase）。</li><li><strong>生命周期方法</strong> — <code>provision()</code> 初始化状态；<code>run()</code> 开始执行并派发；<code>recover()</code> 从持久化恢复中断的运行；<code>adoptPrior(prior)</code> 采纳先前运行的逐节点进度，避免重复派发已完成节点。</li><li><strong>join 评估</strong> — 图引擎判断某节点的所有上游输入是否齐备、从而是否满足执行条件的评估（<code>all</code> / <code>any</code> / <code>quorum</code> 三种汇聚策略）。</li><li><strong>信号传播</strong> — 节点完成时发出带外信号（不嵌入文本、独立传递的控制信令），引擎沿边把信号传播给下游，解锁满足条件的下游节点并派发——整个过程无轮询。</li><li><strong>级联取消 / cascade</strong> — 取消一个节点时，连带取消其所有下游依赖节点。</li><li><strong>循环组 / loop group</strong> — 一组构成有界循环的节点，受最大遍历次数（max_iterations）等上限保护，防止死循环。</li><li><strong>审批门 / HITL（人工在环，Human-in-the-loop）</strong> — 图执行到需要人工确认的节点（<code>needs_approval</code>）时暂停，等待人工批准。</li><li><strong>预算 / budget</strong> — 一次任务允许消耗的总 token/费用上限；耗尽后禁止新的派发。</li><li><strong>持久化与恢复</strong> — 引擎把运行状态写入磁盘，崩溃后可从检查点恢复并继续，避免重复已完成的工作。</li><li><strong>拓扑 / topology</strong> — 协作图的预设结构模式：pipeline（串行）、review-loop（循环）、star（并行）。</li><li><strong>parent</strong> — 协作图保留名，指编排器（父角色）的固定节点。</li><li><strong>边触发方式</strong> — <code>on_signal</code>：收到指定信号时激活这条边；<code>on_condition</code>：指定条件为真时激活这条边。</li></ul></div><p>rolebox <code>1.0.0</code> 将多代理协作统一到 <strong>v2 图执行引擎（graph engine）</strong> 上（CHANGELOG.md:12 引入；当前版本为 <code>1.0.0</code>）。图节点是角色无关的 <code>{agent, prompt}</code> 元组，引擎负责节点生命周期、join 评估、信号传播、级联取消、循环组、审批门、预算、持久化与恢复。</p><p>引擎有<strong>两条</strong>构建路径，最终都落到同一套 v2 执行引擎：</p><ol><li><strong>声明式路径（<code>collaboration:</code>）</strong>——在 <code>role.yaml</code> 中声明拓扑（<code>pipeline</code> / <code>review-loop</code> / <code>star</code>）或自定义边。启动时由 <code>convertCollaborationToGraphDeclaration</code>（<code>src/graph/collaboration-bridge.ts:89</code>）转换为 v2 图声明，并注入 <code>&lt;collaboration_graph&gt;</code> / <code>&lt;collaboration_state&gt;</code> 提示块驱动自动推进。</li><li><strong>命令式路径（<code>graph_*</code> 工具）</strong>——通过 8 个图工具在运行时显式构建与执行图：<code>graph_create</code> / <code>graph_add_node</code> / <code>graph_add_edge</code> / <code>graph_add_loop</code> / <code>graph_run</code> / <code>graph_status</code> / <code>graph_cancel</code> / <code>graph_approve</code>。工具参数详解见<a href="/rolebox-docs/03-Reference/tool-catalog.html#graph-工具v2-引擎">工具目录</a>。</li></ol><hr><h2 id="_1-引擎模型" tabindex="-1">1. 引擎模型 <a class="header-anchor" href="#_1-引擎模型" aria-label="Permalink to &quot;1. 引擎模型&quot;">​</a></h2><h3 id="_1-1-engineruntime" tabindex="-1">1.1 EngineRuntime <a class="header-anchor" href="#_1-1-engineruntime" aria-label="Permalink to &quot;1.1 EngineRuntime&quot;">​</a></h3><p>每次图执行由一个 <code>EngineRuntime</code> 实例承载（<code>EngineRuntime</code> 即该图实例的<strong>运行时对象</strong>，负责持有状态并驱动推进；<code>src/graph/engine/index.ts:107</code>），通过 <code>createEngine(graphDeclaration, options)</code> 构造（<code>src/graph/engine/index.ts:820</code>）。每个 <code>EngineRuntime</code> 拥有一个 <code>EngineState</code>（保存该图全部运行状态的<strong>状态对象</strong>）与一个信号驱动的推进器。</p><p>公开方法（<code>src/graph/engine/index.ts:107-257</code>）：</p><table tabindex="0"><thead><tr><th>方法</th><th>说明</th><th>源码位置</th></tr></thead><tbody><tr><td><code>provision()</code></td><td>初始化状态：注册所有声明节点、引导拓扑（根节点进入 <code>ready</code> 并加入前沿）。幂等</td><td><code>index.ts:116</code></td></tr><tr><td><code>run()</code></td><td>从 <code>idle</code> 过渡到 <code>executing</code> 并派发就绪根节点。需提供 dispatch 缝（<code>dispatch</code> 或 <code>manager</code>）</td><td><code>index.ts:126</code></td></tr><tr><td><code>recover()</code></td><td>从持久化状态恢复中断的图实例（崩溃恢复）：协调 <code>running</code> 节点、重建前沿、排空积压完成</td><td><code>index.ts:138</code></td></tr><tr><td><code>status()</code></td><td>返回当前 <code>EngineState</code> 的只读快照（集合为克隆副本）</td><td><code>index.ts:160</code></td></tr><tr><td><code>adoptPrior(prior, opts)</code></td><td>采纳先前引擎运行的逐节点进度到本次重建的运行时，避免重复派发已完成节点</td><td><code>index.ts:158</code></td></tr><tr><td><code>cancel()</code></td><td>取消进行中的图执行：所有活跃节点 → <code>cancelled</code>，生命周期 → <code>complete</code>。<code>blocked</code> 节点保留等待人工</td><td><code>index.ts:170</code></td></tr><tr><td><code>approveNode(nodeId, payload?)</code></td><td>批准阻塞的 <code>needs_approval</code> 节点：<code>blocked → completed</code>，记录 <code>answer</code> 信号并激活 <code>answer</code> 边（<code>answer</code> 边 = 批准后把结果传给下游的边）</td><td><code>index.ts:181</code></td></tr><tr><td><code>rejectNode(nodeId, reason?)</code></td><td>拒绝阻塞节点：<code>blocked → ready</code>（携带反馈重新进入）或 <code>blocked → escalate</code>（无循环组时）</td><td><code>index.ts:191</code></td></tr><tr><td><code>partialApprove(nodeId, approved, rejected, reason?)</code></td><td>部分批准：接受 <code>approved</code> 分支、取消 <code>rejected</code> 分支的传递依赖，被拒上游重新进入 <code>ready</code></td><td><code>index.ts:206</code></td></tr><tr><td><code>retryNode(nodeId, opts?)</code></td><td>重试终态节点：将目标及其下游子图重置为干净的 <code>pending</code>，可选前置 <code>modifyPrompt</code>，再重新派发</td><td><code>index.ts:230</code></td></tr><tr><td><code>cancelNodes(nodeIds, options?)</code></td><td>取消一个或多个节点（<code>cascade</code> 时级联到传递下游），不触碰整图阶段</td><td><code>index.ts:253</code></td></tr></tbody></table><h3 id="_1-2-enginephase-引擎生命周期" tabindex="-1">1.2 EnginePhase（引擎生命周期） <a class="header-anchor" href="#_1-2-enginephase-引擎生命周期" aria-label="Permalink to &quot;1.2 EnginePhase（引擎生命周期）&quot;">​</a></h3><p>引擎生命周期有 3 个阶段（<code>src/constants.ts:156-160</code>）：</p><table tabindex="0"><thead><tr><th>阶段</th><th>值</th><th>说明</th></tr></thead><tbody><tr><td><code>Idle</code></td><td><code>idle</code></td><td>已构造未运行</td></tr><tr><td><code>Executing</code></td><td><code>executing</code></td><td>派发中就绪节点，推进中</td></tr><tr><td><code>Complete</code></td><td><code>complete</code></td><td>图执行完成（或取消后）</td></tr></tbody></table><p>阶段转换的合法性由 <code>canTransitionPhase</code> 校验、<code>transitionPhase</code> 执行（<code>src/graph/engine/engine-state.ts:116-147</code>）。</p><h3 id="_1-3-nodestatus-节点生命周期" tabindex="-1">1.3 NodeStatus（节点生命周期） <a class="header-anchor" href="#_1-3-nodestatus-节点生命周期" aria-label="Permalink to &quot;1.3 NodeStatus（节点生命周期）&quot;">​</a></h3><p>节点的 9 种状态（<code>src/constants.ts:183-193</code>）：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>正常路径：  pending → ready → running → completed → done</span></span>
<span class="line"><span>暂停路径：  running → blocked (needs_approval) → completed / ready</span></span>
<span class="line"><span>错误路径：  running → escalate → done</span></span>
<span class="line"><span>            running → timeout → done（或 retry → ready）</span></span>
<span class="line"><span>取消路径：  pending / ready → cancelled → done</span></span></code></pre></div><table tabindex="0"><thead><tr><th>状态</th><th>值</th><th>说明</th></tr></thead><tbody><tr><td><code>Pending</code></td><td><code>pending</code></td><td>已注册未就绪</td></tr><tr><td><code>Ready</code></td><td><code>ready</code></td><td>可派发（在前沿中）</td></tr><tr><td><code>Running</code></td><td><code>running</code></td><td>已派发，等待信号</td></tr><tr><td><code>Completed</code></td><td><code>completed</code></td><td>已正常完成</td></tr><tr><td><code>Blocked</code></td><td><code>blocked</code></td><td>等待人工审批（<code>needs_approval</code>）</td></tr><tr><td><code>Timeout</code></td><td><code>timeout</code></td><td>超时（可 retry）</td></tr><tr><td><code>Escalate</code></td><td><code>escalate</code></td><td>出错升级（节点执行出错，进入终态）</td></tr><tr><td><code>Cancelled</code></td><td><code>cancelled</code></td><td>已取消</td></tr><tr><td><code>Done</code></td><td><code>done</code></td><td>终态</td></tr></tbody></table><hr><h2 id="_2-信号驱动的推进-无轮询" tabindex="-1">2. 信号驱动的推进（无轮询） <a class="header-anchor" href="#_2-信号驱动的推进-无轮询" aria-label="Permalink to &quot;2. 信号驱动的推进（无轮询）&quot;">​</a></h2><p>引擎的推进由<strong>派发节点发出的信号</strong>驱动，没有轮询循环。信号经 <code>SignalBridge</code> 进入引擎（<code>src/graph/engine/signal-bridge.ts</code>），在推进锁内执行：解锁满足的下游节点 → 派发就绪节点。整个推进在 <code>_advancing</code> 可重入守卫内运行，保证同一时刻每个图实例只有一个推进临界区（<code>src/graph/engine/engine-advance.ts:8-23</code>）。</p><p>推进相关模块：</p><ul><li><code>engine-advance.ts</code> — 核心推进逻辑、<code>NodeDispatchPort</code> 派发缝、<code>NodeCompletionEvent</code> 完成事件</li><li><code>signal-bridge.ts</code> — 信号进入引擎的桥接</li><li><code>signal-propagation.ts</code> — 信号沿边传播</li><li><code>dispatch-bridge.ts</code> — 引擎与调度系统的派发/完成/用量桥（<code>graphParentContext</code>）</li><li><code>join-evaluator.ts</code> — join 评估（<code>扇入</code>，即多个上游汇合到一个节点）的汇聚策略解析（<code>all</code> / <code>any</code> / <code>quorum</code>）</li><li><code>condition-resolver.ts</code> — 边条件解析（<code>on_condition</code> 边 = 指定条件为真时激活的边，其命名条件在此解析）</li></ul><hr><h2 id="_3-循环组与终止" tabindex="-1">3. 循环组与终止 <a class="header-anchor" href="#_3-循环组与终止" aria-label="Permalink to &quot;3. 循环组与终止&quot;">​</a></h2><ul><li><code>loop-group-executor.ts</code> — 有界循环编排原语：<code>executeLoopStep</code>（循环组成员终止信号的汇聚收敛决策，协调遍历计数、revise 重新派发、升级级联、上游取消）、<code>recordConvergenceOutput</code> / <code>resetConvergenceTracker</code> / <code>fingerprintPayload</code> / <code>extractUnresolved</code></li><li><code>engine-termination.ts</code> — 引擎级终止评估</li><li><code>node-retry.ts</code> — <code>retryNode</code> / <code>resetNodeForRetry</code>（终态节点重开与重派发）</li></ul><p>循环组的运行时计数在 <code>EngineState.loopCounters</code> 中维护（<code>src/graph/engine/engine-state.ts:459-487</code>：<code>incrementLoopTraversal</code> / <code>isLoopExhausted</code>）。</p><hr><h2 id="_4-审批门-approval-gate" tabindex="-1">4. 审批门（Approval Gate） <a class="header-anchor" href="#_4-审批门-approval-gate" aria-label="Permalink to &quot;4. 审批门（Approval Gate）&quot;">​</a></h2><ul><li><code>approval-handler.ts</code> — <code>approveBlockedNode</code> / <code>rejectBlockedNode</code> / <code>pruneDownstreamSubgraph</code> / <code>reenterRejectedUpstreams</code> / <code>resetRejectedUpstreams</code> / <code>mergeRejectionFeedback</code></li><li><code>approval-payload.ts</code> — <code>buildApprovalPayload</code>，构造传给下游的批准载荷</li><li>对应工具 <code>graph_approve</code>（<code>src/graph/tools/approve-tools.ts:7-14</code>）</li></ul><p><code>needs_approval: true</code>（<code>needs_approval</code> 即「需要人工批准」的信号/状态）的节点派发后进入 <code>blocked</code>，等待人工审批——此即 <strong>审批门 / HITL（人工在环，Human-in-the-loop）</strong>。引擎在此暂停并发出 <code>[GRAPH BLOCKED]</code> 提示。</p><hr><h2 id="_5-预算" tabindex="-1">5. 预算 <a class="header-anchor" href="#_5-预算" aria-label="Permalink to &quot;5. 预算&quot;">​</a></h2><p><code>budget-bridge.ts</code> 与 <code>budget/</code> 子系统对接，按节点/图消耗累计 token、成本等预算（预算即一次任务允许消耗的总 token/费用上限，耗尽后禁止新的派发）。<code>EngineState</code> 保存预算用量（<code>src/graph/engine/engine-state.ts:55-113</code>：<code>emptyGraphBudget</code> / <code>applyBudgetDelta</code>）。</p><hr><h2 id="_6-级联取消" tabindex="-1">6. 级联取消 <a class="header-anchor" href="#_6-级联取消" aria-label="Permalink to &quot;6. 级联取消&quot;">​</a></h2><p><code>cancellation.ts</code> 与 <code>cascade-canceller.ts</code> 实现取消原语：</p><ul><li><code>cancelNodes(nodeIds, { cascade })</code> — 取消指定节点，<code>cascade</code> 时级联到传递下游</li><li><code>CancelDispatchPort</code> — 取消已派发后台任务的端口</li></ul><hr><h2 id="_7-持久化与事件日志" tabindex="-1">7. 持久化与事件日志 <a class="header-anchor" href="#_7-持久化与事件日志" aria-label="Permalink to &quot;7. 持久化与事件日志&quot;">​</a></h2><table tabindex="0"><thead><tr><th>文件</th><th>路径</th><th>说明</th></tr></thead><tbody><tr><td><code>engine-{slug}.json</code></td><td><code>.rolebox/state/engine-{slug}.json</code></td><td>每个图的持久化状态（阶段、节点生命周期、预算、前沿、循环组、检查点）。路径由 <code>engineStatePath()</code> 计算（<code>src/graph/engine/engine-persistence.ts:388-393</code>）</td></tr><tr><td><code>graph-events-{hash}.ndjson</code></td><td><code>.rolebox/state/graph-events-{hash}.ndjson</code></td><td>引擎写侧事件的追加式 NDJSON 事件日志（节点派发、终止转换、阶段变化、预算更新）。路径由 <code>graphEventsPath()</code> 计算（<code>src/graph/engine/graph-events.ts:106-112</code>）</td></tr></tbody></table><p>持久化模块：<code>engine-persistence.ts</code>（<code>serializeEngineState</code> / <code>deserializeEngineState</code> / <code>loadEngineStateFromJson</code> / <code>markDirty</code> / <code>shouldPersist</code>）。</p><p>恢复模块：<code>engine-recovery.ts</code>、<code>engine-startup.ts</code>（启动时检测旧位置并搬移）。</p><hr><h2 id="_8-协作图桥接-声明式-→-引擎" tabindex="-1">8. 协作图桥接（声明式 → 引擎） <a class="header-anchor" href="#_8-协作图桥接-声明式-→-引擎" aria-label="Permalink to &quot;8. 协作图桥接（声明式 → 引擎）&quot;">​</a></h2><p><code>collaboration-bridge.ts</code> 将声明式 <code>collaboration:</code> 配置转换为 v2 图声明：</p><table tabindex="0"><thead><tr><th>函数</th><th>源码位置</th><th>说明</th></tr></thead><tbody><tr><td><code>convertCollaborationToGraphDeclaration(collab, opts)</code></td><td><code>collaboration-bridge.ts:89</code></td><td>把协作图转换为无损的 v2 图声明</td></tr><tr><td><code>autoConvertCollaboration(collab, opts)</code></td><td><code>collaboration-bridge.ts:168</code></td><td>自动转换并返回 v2 图声明</td></tr><tr><td><code>graphDeclarationToResolvedGraph(...)</code></td><td><code>collaboration-bridge.ts:197</code></td><td>将图声明反转为 <code>ResolvedGraph</code>（用于协作图运行时）</td></tr></tbody></table><hr><h2 id="_9-工具层" tabindex="-1">9. 工具层 <a class="header-anchor" href="#_9-工具层" aria-label="Permalink to &quot;9. 工具层&quot;">​</a></h2><p><code>graph/tools/</code> 目录承载命令式 <code>graph_*</code> 工具：</p><ul><li><code>index.ts</code> — <code>createGraphTools()</code>（<code>src/graph/tools/index.ts:151-160</code>）注册 8 个工具</li><li><code>graph-tools.ts</code> — <code>createGraphToolSet()</code>（<code>src/graph/tools/graph-tools.ts:2384</code>）核心工具集</li><li><code>approve-tools.ts</code> — <code>graph_approve</code></li><li><code>status-queries.ts</code> — <code>graph_status</code> 查询</li><li><code>persisted-state.ts</code> — 持久化状态工具</li></ul><p>每个工具的完整参数与语义见<a href="/rolebox-docs/03-Reference/tool-catalog.html#graph-工具v2-引擎">工具目录：Graph 工具</a>。</p><hr><h2 id="引用索引" tabindex="-1">引用索引 <a class="header-anchor" href="#引用索引" aria-label="Permalink to &quot;引用索引&quot;">​</a></h2><table tabindex="0"><thead><tr><th>主题</th><th>文件</th><th>行号</th></tr></thead><tbody><tr><td><code>EngineRuntime</code> 接口</td><td><code>src/graph/engine/index.ts</code></td><td>107-257</td></tr><tr><td><code>createEngine()</code></td><td><code>src/graph/engine/index.ts</code></td><td>820-827</td></tr><tr><td><code>EnginePhase</code></td><td><code>src/constants.ts</code></td><td>156-165</td></tr><tr><td><code>NodeStatus</code></td><td><code>src/constants.ts</code></td><td>183-198</td></tr><tr><td>阶段转换</td><td><code>src/graph/engine/engine-state.ts</code></td><td>116-147</td></tr><tr><td>预算工具</td><td><code>src/graph/engine/engine-state.ts</code></td><td>55-113</td></tr><tr><td>循环计数</td><td><code>src/graph/engine/engine-state.ts</code></td><td>459-487</td></tr><tr><td>引擎推进</td><td><code>src/graph/engine/engine-advance.ts</code></td><td>1-23</td></tr><tr><td><code>convertCollaborationToGraphDeclaration</code></td><td><code>src/graph/collaboration-bridge.ts</code></td><td>89</td></tr><tr><td><code>createGraphTools()</code></td><td><code>src/graph/tools/index.ts</code></td><td>151-160</td></tr><tr><td>引擎状态路径</td><td><code>src/graph/engine/engine-persistence.ts</code></td><td>388-393</td></tr><tr><td>事件日志路径</td><td><code>src/graph/engine/graph-events.ts</code></td><td>106-112</td></tr></tbody></table><hr><h2 id="下一步" tabindex="-1">下一步 <a class="header-anchor" href="#下一步" aria-label="Permalink to &quot;下一步&quot;">​</a></h2><ul><li><a href="/rolebox-docs/02-Guide/collaboration-graph.html">协作图</a> — 声明式 <code>collaboration:</code> 拓扑与自定义流</li><li><a href="/rolebox-docs/03-Reference/tool-catalog.html">工具目录</a> — <code>graph_*</code> 工具完整参数</li><li><a href="/rolebox-docs/04-Advanced/runtime-behavior.html">运行时行为</a> — 协作图运行时状态与推进</li><li><a href="/rolebox-docs/04-Advanced/termination-conditions.html">终止条件</a> — 循环终止、收敛与超时</li></ul>`,61)])])}const b=d(a,[["render",r]]);export{g as __pageData,b as default};
